-- lazaron-biotechnologies-pty-ltd-de-wilgers (owner)
UPDATE businesses SET description = 'Lazaron Biotechnologies (Pty) Ltd is a private company based at The Green Hill Village Office Park in Die Wilgers, Pretoria. The business works as a stem-cell storage facilitator, offering cord-blood and stem-cell storage to expectant parents and families who want to store their baby''s cord blood privately. Company history describes Lazaron as South Africa''s first private cord-blood stem-cell bank, and historical material states that its services were provided to thousands of parents. The company was founded in 2011, and its LinkedIn profile lists it as a Pretoria-based private company. Business registry records show the company as in business. Much of the available operational information is historical, so prospective clients should confirm the current storage services directly with the company before making a decision.', description_enriched_at = datetime('now') WHERE slug = 'lazaron-biotechnologies-pty-ltd-de-wilgers' AND description = 'A stem cell storage facilitator in De Wilgers preserving umbilical cord blood and tissue stem cells for future medical use, a spin-off from Stellenbosch University founded in the mid-2000s.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
