UPDATE businesses SET description = 'Legacy Industrial Supplies is an industrial hardware and safety-products supplier based in Silverton, Pretoria, at 457 Moreleta Street (C/O Dykor). The company supplies power tools, welding equipment and consumables, abrasives, paints and coatings, industrial gases and general hardware. Its range also includes personal protective equipment, workwear and safety footwear. The business serves industrial, construction, maintenance and welding customers, as well as trade buyers looking for tools and protective gear. The company''s website shows brands including DEWALT, Dromex, ESAB, HiKOKI and Jonsson Workwear. Its website also publishes contact details and trading hours, so customers can check when the store is open before visiting.', description_enriched_at = datetime('now') WHERE slug = 'legacy-industrial-supplies-salieshoek' AND description = 'A family-owned industrial supplies retailer established in 2014, selling power tools, hand tools, welding equipment, PPE and workwear, abrasives and hardware from brands including Einhell, Makita, DeWalt and Bosch.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
