-- loadtech-load-cells-pty-ltd-rooihuiskraal (owner)
UPDATE businesses SET description = 'Loadtech Load Cells (Pty) Ltd designs, manufactures and supplies high-precision load cells, force-measurement equipment and instrumentation. Its product range includes tension and compression load cells, weighing modules, wireless load cells and custom load cells, supplied as part of integrated weighing systems. The company was founded in 1987 and manufactures in South Africa for local and export markets. Its customers include businesses in mining, manufacturing, logistics, agriculture, construction, transport and warehousing, including heavy-duty applications. Loadtech provides calibration, service-level agreements, on-call technical support, and installation and commissioning. Customers can rely on the company for support after the equipment is supplied. The head office is at 134 Sarel Baard Crescent, Centurion.', description_enriched_at = datetime('now') WHERE slug = 'loadtech-load-cells-pty-ltd-rooihuiskraal' AND description = 'Founded in 1987, Loadtech Load Cells engineers, manufactures and supplies load cells, force-measurement devices and integrated weighing systems, supporting mining, manufacturing, logistics, agriculture and construction operations across southern Africa.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
