UPDATE businesses SET description = 'Lucky Bread Company is an artisan bakery and café with a branch at Brooklyn Mall, on the corner of Veale and Fehrsen Street in Nieuw Muckleneuk, Pretoria. The bakery makes wood-fired bread and handmade pastries using local stone-ground flour. The café serves coffee, breakfast and lunch, and customers can also take their orders away. The business offers catering and wholesale supply for businesses and events that need bread and baked goods in quantity. The company''s official store directory lists Brooklyn Mall as a current operating location, so the branch is listed as open. Diners looking for a bakery café in Muckleneuk can come for breakfast or lunch or buy fresh bread to take home.', description_enriched_at = datetime('now') WHERE slug = 'lucky-bread-company-brooklyn-mall-muckleneuk' AND description = 'This Brooklyn Mall branch is decorated in a retro-Americana style with brass, timber and leather details evoking 1938 steam trains, and sits beside the escalator up to the cinemas.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
