UPDATE businesses SET description = 'Lyttleton Mining Supplies CC supplies engineering products to mines and industrial customers, with a focus on material handling and power transmission. Its product range includes fasteners, motors, oils, probes, stainless steel, steel, cranes, tackle and winches. The business also offers engineering consultation and the design and supply of conveyor systems. Its customers include mining, manufacturing and other industrial operations. The company is based at 8 Amandelboom Street in Zwartkop X4, Centurion. M2North identifies Lyttleton Mining Supplies as a manufacturer and OEM, supplier, contractor and sole distributor, and records it as a Level 1 B-BBEE supplier. Its products and services are aimed at mines and industrial customers that need engineering supplies and conveyor systems.', description_enriched_at = datetime('now') WHERE slug = 'lyttleton-mining-supplies-c-c-lyttelton' AND description = 'Lyttleton Mining Supplies CC designs and supplies engineering solutions in material handling and power transmission to mines and industry, offering engineering consultation and holding a Level 1 BBBEE rating.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
