UPDATE businesses SET description = 'Matshoga Security Services & VIP Protection provides security services for residential, retail and industrial clients. Its security services include guarding, armed response, residential protection, retail security and industrial security. The business also offers VIP and executive protection, covering protective security, threat assessment and logistical planning for executives, high-net-worth individuals and public figures. Matshoga appears in the BACSA participant database as an approved private security company, with coverage across several South African provinces. Its clients include homeowners, retail businesses and industrial operators, as well as executives who need dedicated protection. Its services are offered to both residential and business clients, from routine guarding to armed response and executive protection. The business is verified as an approved private security company.', description_enriched_at = datetime('now') WHERE slug = 'matshoga-security-services-vip-protection-hesteapark' AND description = 'MATSHOGA SECURITY SERVICES & VIP PROTECTION is a Pretoria-based security firm offering armed response along with industrial, residential and retail guarding, tailoring protection strategies to each client''s specific needs.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
