UPDATE businesses SET description = 'MJ Construction Pretoria is a residential construction and renovation business whose current listings place it at Disselboom Avenue in Wapadrand, Pretoria. The company builds new homes and does home renovations, including garages, entrance gates, kitchen renovations, braai areas, home additions and general maintenance. Its services also extend to solar installations, battery and inverter systems, home automation and audio, and related home-improvement work. Homeowners planning a new build, an extension or a renovation are the business''s main customers. Its galleries show completed projects for new homes, renovations, kitchens, swimming pools, flooring, solar installations and home audio. The company''s services cover the full range of residential building work, from new homes and additions to renovations, kitchens and maintenance.', description_enriched_at = datetime('now') WHERE slug = 'mj-construction-pretoria-clydesdale' AND description = 'MJ Construction Pretoria is an NHBRC-registered, family-run building company based in Wapadrand that handles renovations of all sizes, from kitchens and bathrooms to structural upgrades and new home builds.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
