UPDATE businesses SET description = 'Namib Fire sells Namibian Kameeldoring braai firewood, firelighters and braai accessories. The company describes Kameeldoring as dry, dense and slow-burning wood suited to braai use, and it sells the wood in 20kg bags. Its firelighters are sold under the Namib Fire name. Pretoria braai customers can have firewood delivered across the city, with a minimum order of five bags. Braai accessories are delivered nationwide, so buyers outside Pretoria can also order them. The company''s range is aimed at Pretoria braai customers and national braai-accessory buyers. Its website sets out its delivery options for Pretoria firewood orders and nationwide accessory orders.', description_enriched_at = datetime('now') WHERE slug = 'namib-fire-kameeldrift' AND description = 'Namib Fire supplies Kameeldoring braai wood and firewood sourced from the Gemsbokpan farm in Namibia, selling dry, slow-burning, almost smokeless wood packed in 20kg bags with delivery across Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
